<?php
declare(strict_types=1);
/** Registra intencao em analise. A triagem capturada nunca autoriza movimento financeiro. */
final class GFRefundCaseQA
{
    private static function json(array $a):string{return json_encode($a,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES);}
    public static function create(PDO $db,int $actor,int $order,string $key,mixed $amount,string $reason):array
    {
        $owned=false;$phase='GUARD';try{
            GFDirectBilling::guard($db);if($db->inTransaction())throw new LogicException('FIN_REFUND_CASE_OWNS_TRANSACTION_REQUIRED');$reason=trim($reason);if(!is_string($amount) || !preg_match('/^[a-f0-9]{32}$/D',$key) || !mb_check_encoding($reason,'UTF-8') || mb_strlen($reason,'UTF-8')<20 || mb_strlen($reason,'UTF-8')>500)throw new DomainException('parametro_ou_motivo_invalido',422);
            $phase='CAPTURE_REVIEW';$r=GFRefundReviewQA::review($db,$actor,$order,$amount);if(!$r['ok'])return $r;$review=$r['report'];if($review['partial_request'])throw new DomainException('caso_parcial_ainda_nao_suportado',422);
            // Snapshot observado antes da insercao; aprovacao futura deve revalidar integralmente.
            $request=['actor'=>$actor,'order'=>$order,'key'=>$key,'amount'=>$review['requested_amount'],'reason'=>$reason];$hash=hash('sha256',self::json($request));$op=hash('sha256','r11be|'.$actor.'|'.$key);
            $db->beginTransaction();$owned=true;$phase='AUTHORIZE_CURRENT';$q=$db->prepare('SELECT tipo,ativo FROM usuarios WHERE id=? LOCK IN SHARE MODE');$q->execute([$actor]);$u=$q->fetch(PDO::FETCH_ASSOC);if(!$u || $u['tipo']!=='admin' || (int)$u['ativo']!==1)throw new DomainException('acesso_negado',403);
            $phase='LOCK_TARGET';if(count(GFReconciliation::rows($db,'SELECT id FROM pedidos WHERE id=?',[$order],true))!==1)throw new DomainException('pedido_nao_encontrado',404);
            $phase='REPLAY';$old=GFReconciliation::rows($db,'SELECT * FROM fin3_refund_cases_qa WHERE operation_key=?',[$op],true);if($old){$a=$old[0];$body=json_decode($a['report_json'],true,512,JSON_THROW_ON_ERROR);$checksum=$body['evidence_sha256']??'';unset($body['evidence_sha256']);if((int)$a['order_id']!==$order || (int)$a['actor_id']!==$actor || $a['status']!=='em_analise' || $a['requested_amount']!==$request['amount'] || $a['reason']!==$reason || $a['request_sha256']!==$hash || $a['review_sha256']!==$checksum || !hash_equals($checksum,hash('sha256',self::json($body))) || ($body['source_sha256']??null)!==$a['source_sha256'] || ($body['actor_id']??null)!==$actor || ($body['order_id']??null)!==$order || ($body['requested_amount']??null)!==$a['requested_amount'])throw new DomainException('idempotencia_ou_evidencia_divergente',409);if(($body['actions']??null)!==['refund_authorized'=>false,'refund_executed'=>false,'invoice_rewrite_allowed'=>false,'compensation_authorized'=>false,'external_transport'=>false])throw new DomainException('caso_contem_autorizacao_invalida',409);$changed=$a['source_sha256']!==$review['source_sha256'];$db->commit();$owned=false;return self::result($op,$order,true,$changed);}
            if(GFReconciliation::rows($db,'SELECT operation_key FROM fin3_refund_cases_qa WHERE order_id=?',[$order],true))throw new DomainException('pedido_ja_possui_caso_em_analise',409);
            $phase='INSERT_CASE';$now=date('Y-m-d H:i:s');$db->prepare("INSERT INTO fin3_refund_cases_qa(operation_key,order_id,actor_id,status,requested_amount,source_sha256,review_sha256,request_sha256,reason,report_json,created_at) VALUES (?,?,?,'em_analise',?,?,?,?,?,?,?)")->execute([$op,$order,$actor,$request['amount'],$review['source_sha256'],$review['evidence_sha256'],$hash,$reason,self::json($review),$now]);$phase='COMMIT';$db->commit();$owned=false;return self::result($op,$order,false,null);
        }catch(Throwable $e){if($owned && $db->inTransaction())$db->rollBack();$http=$e instanceof DomainException && in_array($e->getCode(),[403,404,409,422],true)?$e->getCode():500;$d=['project'=>'GuinchaFacil','class'=>self::class,'function'=>'create','component'=>'refund_cases','phase'=>$phase,'status'=>$http===500?'FAIL':'REJECTED','error'=>$e->getMessage(),'file'=>basename($e->getFile()),'line'=>$e->getLine(),'exception'=>$e::class,'sqlstate'=>$e instanceof PDOException?($e->errorInfo[0]??null):null,'driver_code'=>$e instanceof PDOException?($e->errorInfo[1]??null):null,'remaining_percent'=>30];error_log(json_encode($d,JSON_THROW_ON_ERROR));return ['ok'=>false,'http'=>$http,'erro'=>$http===500?'caso_indisponivel':$e->getMessage(),'diagnostic'=>$d];}
    }
    private static function result(string $op,int $order,bool $replayed,?bool $changed):array{return ['ok'=>true,'http'=>200,'case_key'=>$op,'order_id'=>$order,'status'=>'em_analise','replayed'=>$replayed,'snapshot_changed_since_capture'=>$changed,'snapshot_scope'=>'OBSERVED_BEFORE_CASE_INSERT','requires_fresh_revalidation'=>true,'refund_authorized'=>false,'refund_executed'=>false,'compensation_authorized'=>false,'external_transport'=>false];}
}
